def run(context): latest_trade_date = context['latest_trade_date']; latest_snapshot_date = context['latest_snapshot_date']; threshold_days = context['threshold_days']; from datetime import datetime; today = datetime.today().date(); days_stale = (today - max(latest_trade_date, latest_snapshot_date)).days; is_fresh = days_stale <= threshold_days; return {'is_fresh': is_fresh, 'days_stale': days_stale}